#!/usr/bin/env python3
from pathlib import Path
import re,json,hashlib
root=Path(__file__).resolve().parents[2];out=root/'docs/reports/cliff-formations'
log=(out/'volumes.log').read_text()
m=re.search(r'FORMATION_SOLIDS count=(\d+) triangles=(\d+) floor_tests=(\d+) shifted=(\d+) closed_convex=PASS union_rays=(\d+)',log)
assert m and 'FORMATION_DETERMINISM identical_vertices=PASS' in log
count,triangles,tests,shifted,rays=map(int,m.groups())
assert 'collision_heights=unchanged floor_triangles=unchanged' in log
runtime=['src/world/CanyonAppearance.cpp','src/world/CliffFacetRefinement.cpp','src/world/CanyonTerrain.cpp','src/render/CanyonScene.cpp','src/core/Game.cpp','assets/visual/canyon.cfg']
status={'status':'isolated_volume_geometry_cleanup','seed':1866,'scene':'profile-works','game_zoom_percent':160,'frames':60,'closed_solids':count,'exposed_union_triangles':triangles,'convex_union_reference_rays_per_build':rays,'protected_floor_overlap_tests_per_build':tests,'volumes_shifted_clear_of_floor':shifted,'deterministic_repeated_vertices':True,'floor_triangles_unchanged':True,'collision_heights_unchanged':True,'production_runtime_hashes':{f:hashlib.sha256((root/f).read_bytes()).hexdigest() for f in runtime},'remaining':['Art refinement: outlines, roof shapes and end/backing transitions','Final backing/body welding and joins to untouched terrain','Edge chips, finer ground-contact debris and grounded terrace vegetation','Multi-seed validation and seed-driven composition across rooms','No production rollout or exact reference-match claim']}
geometry_tests=(out/'geometry-tests.log').read_text()
assert 'PASS rock formations:' in geometry_tests
previous=json.loads((out/'pre-cleanup-status.json').read_text())
assert status['production_runtime_hashes']==previous['production_runtime_hashes'], 'Production runtime changed during isolated cleanup'
status['cleanup']={'raised_backing_removed':True,'buried_volume_bases':True,'old_protruding_facets_lowered':True,'backing_clipped_clear_of_floor':True,'backing_tapers_to_sand':True,'convex_coplanar_pieces_consolidated':True,'double_precision_plane_intersections':True,'previous_union_triangles':previous['exposed_union_triangles'],'synthetic_wall_seeds':[0,42,1866],'synthetic_seed_scope':'geometry and ray checks only; no multi-room visual acceptance'}
if (out/'phase2/status.json').exists():
    status['latest_refinement']='phase2/status.json'
elif (out/'phase1/status.json').exists():
    status['latest_refinement']='phase1/status.json'
(out/'status.json').write_text(json.dumps(status,indent=2)+'\n')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Canyon formations — complete-volume geometry cleanup</title><style>*{box-sizing:border-box}body{margin:0;background:#20272b;color:#eadfce;font:17px/1.55 system-ui}main{max-width:1550px;margin:auto;padding:28px}a{color:#9cdccf}p{max-width:1120px}h2{margin-top:34px}.status{padding:16px;border-left:5px solid #dfbd7f;background:#2b383c}.wide{overflow:auto}.sheet{display:grid;grid-template-columns:1fr 1fr;width:max-content}.sheet figure{margin:0;border:2px solid #56636a}.sheet figcaption{height:40px;padding:5px 16px;font:600 20px/30px system-ui;background:#2b383d}.crop{width:1320px;height:600px;position:relative;overflow:hidden}.crop img{width:2880px;height:1800px;max-width:none;position:absolute;left:-760px;top:0}.full img{display:block;width:1440px;height:900px}.native{width:100%;height:auto}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}code,pre{color:#ebc68c}</style><main><h1>Complete rock volumes: geometry cleanup</h1><p class="status"><strong>Prototype, not a production replacement.</strong> The selected wall now uses genuine thick rock volumes, exposed union faces, independent heights and local shoulders. The regular game remains on A. This blockout establishes primary shapes but still needs art refinement; it is not an exact reference match.</p><p><a href="../../canyon_rock_formations_plan.md">Saved Markdown plan</a> · <a href="comparison.png">Enlarged wall comparison</a> · <a href="full-comparison.png">Full native comparison</a> · <a href="wireframe.png">Union polygon wireframe</a> · <a href="triangles.png">Actual triangle wireframe</a> · <a href="status.json">Validation/status data</a></p><h2>Cleanup and its limits</h2><p>The previous view had a raised backing strip, beveled bases and protruding old facet vertices. Together they left zigzag joins and small plates around the new rocks. This pass lowers the backing to the existing ground contour, buries the closed bases, includes the protruding old skin in the lowering region, trims its inherited overlap with protected floor triangles, and merges safe convex coplanar fragments. Broad faces and primary outlines are preserved. Double-precision plane-intersection classification fixes an open-solid failure exposed by synthetic seed coverage.</p><p><a href="geometry-tests.log">Focused geometry tests</a> cover real interior holes, concave recesses, separated regions, coplanar ownership, replay and three synthetic-wall seeds (0, 42, 1866), each with 640 independent rays. A backing fixture checks the ground taper, removal of old facets over protected floor, and unchanged floor/collision values. These checks do not establish visual acceptance across rooms. <a href="regression-tests.log">CTest regression results</a>. The original A baseline remains available in <a href="before.png">this capture</a>; the comparisons below show the prototype immediately before and after cleanup.</p><h2>Same scene, camera, seed and rendering</h2><p>Seed 1866, Works profile, room 2, 60 simulation frames, original style, 1440 × 900 native capture, 160% game zoom. The upper wall between the trail posts is the experiment. The two views below use identical pixel crops enlarged 2×; the camera was not moved.</p><div class="wide"><div id="wall-sheet" class="sheet"><figure><figcaption>Volume prototype before cleanup</figcaption><div class="crop"><img src="pre-cleanup-volumes.png"></div></figure><figure><figcaption>Volume prototype after cleanup</figcaption><div class="crop"><img src="volumes.png"></div></figure></div></div><h2>Full scene</h2><div class="wide"><div id="full-sheet" class="sheet full"><figure><figcaption>Volume prototype before cleanup</figcaption><img src="pre-cleanup-volumes.png"></figure><figure><figcaption>Volume prototype after cleanup</figcaption><img src="volumes.png"></figure></div></div><h2>Actual volume construction</h2><p>Five main masses include one dominant formation, with three lower shoulders and four base rocks. Every rock is a closed convex solid defined by broad side planes, a base, roof planes and selected bevel planes. Asymmetric outlines and independent heights establish the large shapes before triangulation. No front-skin displacement or surface-noise pass is used for these masses.</p><p>Overlapping rock volumes are combined by extracting their exposed boundary. Faces buried in another rock are removed. A ground-level retained backing ties the masses to the original ground boundary; the old high terrace band is lowered only within this visual test region. The old 0.6 m strip now meets the original 0.12 m ground contour and tapers into the sand behind it. Inherited old facets that projected over protected floor triangles are clipped away, leaving the original floor unchanged. Closed rock bases extend below it to avoid exposed base plates. Some buried rock/backing interfaces remain for final welding. This is not a fully optimized final terrain mesh.</p><p>The first blockout had repeated capped rectangular shapes. Subsequent explicit profile changes use asymmetric rounded polygon footprints, unequal face widths, varying roof planes and selective bevels. Compare the <a href="first-volumes.png">first capped blockout</a> and <a href="rectangular-blockout.png">intermediate rectangular massing</a>. The current result has more substantial forms and quieter faces, but its top outlines and shoulders remain too simple to call the art direction finished.</p><h2>Wireframes</h2><p>Adjacent coplanar union fragments are merged only when their combined boundary stays convex and preserves area. True recesses and holes remain open. The polygon view retains cuts where a convex merge would change the surface. The triangle view shows the actual internal triangulation. Both are native renders of the new solid boundary, not concept images.</p><div class="pair"><a href="wireframe.png"><img class="native" src="wireframe.png"></a><a href="triangles.png"><img class="native" src="triangles.png"></a></div><h2>Validation</h2><p>'''+str(count)+''' closed convex input solids; '''+str(triangles)+''' triangles in the exposed rock union, below the prototype's 2,400-triangle limit. Every input solid checks two faces per edge, positive volume and vertex containment in its defining planes. '''+str(rays)+''' independent convex-plane rays per construction agree with the extracted union triangles within 4 mm. Two constructions from the same seed produce identical vertices.</p><p>The projected convex footprint of each rock is tested against the existing protected floor triangles using separating axes. '''+str(tests)+''' overlap tests were performed per construction; '''+str(shifted)+''' rocks were moved farther behind the boundary until clear. This protects the floor, roads and exits against new visual rock overlap. All floor triangles and their vertices are verified unchanged, as are both the copied terrain heights and the authoritative arena collision heights.</p><p>The backing change would leave some old plateau plants unsupported. Unsupported old plateau plants are suppressed only in this geometry-only debug view. No new vegetation, materials, lighting or postprocessing were added. The regular game's assets and generator are unchanged by this experiment.</p><p><a href="build.log">Native build log</a> · <a href="volumes.log">Geometry, floor-clearance, replay and ray checks</a> · <a href="wireframe.log">Wireframe capture</a> · <a href="triangles.log">Triangle capture</a>. These are fixed-seed prototype checks, not an exhaustive multi-floor navigation/performance acceptance. The FPS display in the captures is not a controlled performance comparison. Construction timings include validation and repeated generation.</p><h2>References</h2><div class="pair"><a href="shaded-reference.png"><img class="native" src="shaded-reference.png"></a><a href="wireframe-reference.png"><img class="native" src="wireframe-reference.png"></a></div><h2>Remaining before rollout</h2><p>Refine the main outlines, cap shapes, natural ledge transitions and joins to the untouched canyon. Finalize the body/backing interface and its transitions to untouched terrain. Convex coplanar-fragment consolidation is implemented; this is not a fully welded final union. Then add restrained edge/base detail and grounded vegetation. Three synthetic-wall seeds pass geometry checks; broader rendered room/seed coverage and a seed-driven room composition system remain unimplemented. Do not replace all expedition cliffs on the strength of this one blockout.</p><h2>Run the isolated preview</h2><pre>cmake --build build --target deathward_cliff_alternatives -j4
DW_CLIFF_OPTION=formations ./build/deathward_cliff_alternatives \\
 --mute --smoke --theme canyon --style original --scene profile-works --frames 6000
# Add DW_CLIFF_WIRE=1 or DW_CLIFF_WIRE=triangles.</pre><p>All new geometry code is in <code>tools/cliff_experiments/RockFormations.cpp</code>, linked only into the debug executable. The authored formation descriptors are in its <code>build()</code> function. No new asset dependencies. Recapture with <code>python3 tools/cliff_experiments/formations-capture.py</code>, then regenerate this report with <code>python3 tools/cliff_experiments/formations-report.py</code> and its comparison sheets with <code>node tools/cliff_experiments/formations-export.cjs</code>. Changes are uncommitted.</p></main></html>'''
if (out/'phase2/index.html').exists():
    html=html.replace('<main>', '<main><p class="status">This page preserves the cleanup checkpoint. Continue with the <a href="phase2/index.html">connected plateau, matched comparison and join validation</a>.</p>', 1)
elif (out/'phase1/index.html').exists():
    html=html.replace('<main>', '<main><p class="status">This page preserves the cleanup checkpoint. Continue with the <a href="phase1/index.html">latest Phase 1 shape comparison, annotations and validation</a>.</p>', 1)
(out/'index.html').write_text(html)
